if(!['GET','HEAD'].includes(req.method))return json({ok:false,error:'METHOD_NOT_ALLOWED'},405);
if(!['/','/gestason','/gestapp','/v03'].includes(u.pathname))return new Response('Not found',{status:404,headers:H});
